def factorial(n):
    """
    Calculate the factorial of a given number using recursion.

    Parameters:
    n (int): A non-negative integer whose factorial is to be computed.

    Returns:
    int: The factorial of the given number n.
    Raises:
    ValueError: If n is negative, as factorial is not defined for negative numbers.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def main():
    try:
        n = int(input())
        result = factorial(n)
        print(result)
    except ValueError as ve:
        print(str(ve))

if __name__ == "__main__":
    main()

def calculate_shannon_diversity(species_counts):
    # Handle empty input list
    if not species_counts:
        return 0.0

    total_individuals = sum(species_counts)

    # Calculate Shannon diversity index
    shannon_index = 0.0
    for count in species_counts:
        if count > 0:
            proportion = count / total_individuals
            shannon_index -= proportion * math.log(proportion)

    return shannon_index

