class Stack:
    def __init__(self, capacity=10):
        self.capacity = capacity
        self.stack = []

    def push(self, item):
        if len(self.stack) >= self.capacity:
            print("Exception: Stack is full")
        else:
            self.stack.append(item)

    def pop(self):
        if not self.stack:
            print("Exception: Stack is empty")
        else:
            print(self.stack.pop())

    def peek(self):
        if not self.stack:
            print("Exception: Stack is empty")
        else:
            print(self.stack[-1])


def main():
    stack = Stack()
    while True:
        try:
            cmd = input().strip()
        except EOFError:
            break
        if cmd == "end":
            break
        if cmd.startswith("push "):
            _, num = cmd.split()
            stack.push(int(num))
        elif cmd == "pop":
            stack.pop()
        elif cmd == "peek":
            stack.peek()

